const importedMember = (message: ArchivedMessage): Member => {
  if (message.author.includes("IRO+運営") || message.author.includes("運営事務局")) return operator;
  return { id: `discord-${message.userId || message.author}`, name: message.author, avatar: "/pwa/icon-1024.png", rank: "regular", points: 0, level: 1, branch: "kanto", generation: 1, bio: "", interests: [], role: "member", joinedAt: "2024-01-01" };
};
const reactions = (source: Record<string, number>): Record<string, string[]> | undefined => {
  const entries = Object.entries(source).filter(([, count]) => count > 0).map(([emoji, count]) => [emoji, Array.from({ length: count }, (_, index) => `discord-${emoji}-${index + 1}`)]);
  return entries.length ? Object.fromEntries(entries) : undefined;
};
const images = (files: string[]) => files.filter((file) => !/\.(mov|mp4|m4v|webm)$/i.test(file));
const videos = (files: string[]) => files.filter((file) => /\.(mov|mp4|m4v|webm)$/i.test(file));

export const SEEDED_GOURMET_CONTESTS: { thread: BoardThread; comments: BoardComment[] }[] = archive
  .map((contest) => {
    const [initial, ...replies] = contest.messages;
    const threadId = `imported-contest-${contest.id}`;
    const threadImages = images(initial.localAttachments);
    const threadVideos = videos(initial.localAttachments);
    const comments: BoardComment[] = replies.map((message) => ({
      id: message.id,
      threadId,
      author: importedMember(message),
      content: message.content,
      createdAt: message.createdAt,
      images: images(message.localAttachments),
      videos: videos(message.localAttachments),
      reactions: reactions(message.reactions),
      isSystem: /結果発表|優勝者発表/.test(message.content),
    }));
    const lastUpdated = comments.at(-1)?.createdAt ?? initial.createdAt;
    const thread: BoardThread = {
      id: threadId,
      title: contest.title,
      author: importedMember(initial),
      category: "gourmet-contest",
      commentCount: comments.length,
      lastUpdated,
      preview: initial.content,
      isRecruiting: false,
      images: threadImages,
      videos: threadVideos,
      gourmetContest: {
        commentDeadline: deadlines[contest.round],
        ...(contest.round === 25 ? { prizePoints: 3000 } : { prizeTitle: contest.round === 1 ? "IRO+イベント割引券 5,000円分" : "IRO+イベントクーポン 3,000円分", prizeDescription: "Discordから移行した過去大会", prizeExpiresAt: deadlines[contest.round], archived: true, winnerName: winners[contest.round] }),
      },
    };
    return { thread, comments };
  })
  .sort((a, b) => Number(b.thread.title.match(/第(\d+)回/)?.[1] ?? 0) - Number(a.thread.title.match(/第(\d+)回/)?.[1] ?? 0));
